head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil17100";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil17100.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_table_10_ontabclick
 * @description tab_table_10 탭 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tab_table_10_ontabclick = async function(e){ try { const i = (e && e.selectedTabIndex !== undefined) ? e.selectedTabIndex : (typeof e === 'number' ? e : (($c.util.getComponent('table_10') || {}).getSelectedTabIndex ? $c.util.getComponent('table_10').getSelectedTabIndex() : 0)); const fns = [async function(){ await scwin.goRegister() }, async function(){ await scwin.searchQnaResult() }]; if (i !== 0 && fns[i]) fns[i](); } catch (err) { await $c.exception.handleError(err, { notify: 'none', context: 'tab_table_10' }); } };

/**
 * @method
 * @name txa_content_onkeyup
 * @description 「질의내용」 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_content_onkeyup = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_content"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17100.txa_content_onkeyup' }); }
};

/**
 * @method
 * @name txa_content_onchange
 * @description 「질의내용」 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_content_onchange = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_content"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17100.txa_content_onchange' }); }
};

/**
 * @method
 * @name img_37_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_37_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17100.img_37_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchQnaResult
 * @description search Qna Result 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchQnaResult = async function () {
    const sbmOptions = {
        id: "tx_fn_searchQnaResult",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_searchQnaResultReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goRegister
 * @description go Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goRegister = async function () {
    const sbmOptions = {
        id: "tx_fn_goRegister",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_goRegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_registerReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchQnaResult
 * @description search Qna Result 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchQnaResult = async function () {
    const frm = (document.QnaForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_searchQnaResultReq').set('method', 'searchQnaResult');
    const nr = await scwin.tx_fn_searchQnaResult();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil17101/jldfil17101.xml", { "method": 'searchQnaResult' });
    }
};

/**
 * @method
 * @name goRegister
 * @description go Register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goRegister = async function () {
    const frm = (document.QnaForm || { elements: [] });
    $c.util.getComponent('dma_searchQnaResultReq').set('method', 'searchQnaApply');
    frm.action = 'qna.do';
    await scwin.tx_fn_goRegister();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const frm = (document.QnaForm || { elements: [] });
    if (await scwin.checkRequired($c.util.getComponent('slc_jobType'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_title'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('txa_content'))) {
        return;
    }
    frm.action = 'qna.do';
    $c.util.getComponent('dma_searchQnaResultReq').set('method', 'registerQna');
    await scwin.tx_fn_register();
};

/**
 * @method
 * @name checkByte
 * @description check Byte 처리
 * @param {*} _obj _obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkByte = async function (_obj) {
    const standardByte = 2000;
    const contnByte = scwin.getByte(_obj);
    const byteCntObj = $c.util.getComponent("txt_byteCnt");
    byteCntObj.innerText = "질의내용(" + (contnByte) + "/2000 byte)";
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
};

/**
 * @method
 * @name getByte
 * @description get Byte 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.getByte = function (_obj) {
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0D') {
            iCounts++;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
};

/**
 * @method
 * @name calcContn
 * @description calc Contn 처리
 * @param {*} _contn _contn
 * @param {*} _maximum _maximum
 * @returns {void}
 * @hidden N
 */
scwin.calcContn = function (_contn, _maximum) {
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
        if (escape(ch) === '%0D') {
            inc = 1;
        } else {
            if (escape(ch).length > 4) {
                inc = 2;
            } else {
                if (ch === '<' || ch === '>') {
                    inc = 4;
                } else {
                    inc = 1;
                }
            }
        }
        nbytes += inc;
        if (nbytes > _maximum) {
            break;
        }
        rContn += ch;
    }
    return rContn;
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};
